import{z as p,x as F,o as n,c as d,q as l,j as s,D as o,d as t,s as i,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"NFA 与 DFA","description":"","frontmatter":{"title":"NFA 与 DFA","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/nfa-dfa.md","filePath":"cs/nfa-dfa.md","lastUpdated":1791063341000}'),D={name:"cs/nfa-dfa.md"};function f(m,a,c,E,B,h){const r=F("Mermaid");return n(),d("div",null,[a[2]||(a[2]=l('<h1 id="nfa-与-dfa" tabindex="-1">NFA 与 DFA <a class="header-anchor" href="#nfa-与-dfa" aria-label="Permalink to &quot;NFA 与 DFA&quot;">​</a></h1><div class="epigraph"><p>非确定机用状态集合响应一个字符；子集构造给出等价的确定机，正则语言不因非确定而变大。</p><footer>—— 据 Rabin and Scott, Finite Automata and Their Decision Problems, 1959；Hopcroft and Ullman, Introduction to Automata Theory 整理</footer></div><p>上一课<a href="/cs/regex-lexer">正则与词法</a>已经用 DFA 最长匹配切记号，并写过「正则 → NFA → DFA」。本课不重做种别与关键字表。缺口是自动机本身：NFA 允许多转移与 \\(\\varepsilon\\)，DFA 每个字符至多一个后继；二者认同一类语言。后课 Thompson 才把正则表达式具体编成 NFA。本课只钉等价与子集构造的形状。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>词法要的是「读完一个字符，下一状态唯一」，否则最长匹配的回退没有确定位置。书写正则时，并与星号自然对应分支与回路，直接画 DFA 很挤。NFA：$ \\delta(q,a)$ 是集合，\\(\\varepsilon\\) 不读字符。接受：存在一条路读完 \\(w\\) 停在接受态。DFA 是 NFA 的特例。缺口是<strong>确定化</strong>：DFA 的一个状态 = NFA 状态的一个子集，\\(\\delta&#39;(S,a)=\\varepsilon\\text{-closure}(\\bigcup_{q\\in S}\\delta(q,a))\\)。</p><p><span class="marginnote">直觉类比：NFA 像同时派出多支探路小队，读完一个字符后凡是能走的路都往前挪；DFA 只有一支小队。子集构造就是把「所有可能的位置组合」各编成一个新状态，于是两台机器认出的串完全一样。</span></p><p>指数爆炸：子集最多 \\(2^{|Q|}\\)。词法器生成器接受这份编译期代价；运行期仍对源长线性。不等价的错觉来自「NFA 好像更强」——语言类相同。</p><p><span class="marginnote">数字实例：NFA 有 10 个状态，子集最多 \\(2^{10}=1024\\) 个——DFA 最坏膨胀一千倍；30 个状态就是 \\(2^{30}\\approx 10^9\\)。所以确定化放在生成期做一次，换来运行期每个字符只走一步。</span></p><h3 id="不是空记号" tabindex="-1">\\(\\varepsilon\\) 不是空记号 <a class="header-anchor" href="#不是空记号" aria-label="Permalink to &quot;$\\varepsilon$ 不是空记号&quot;">​</a></h3><p>\\(\\varepsilon\\) 转移在字符之间，不消耗输入。词法的空lexeme 是另一约定（不要为每种别匹配空串）。本课 \\(\\varepsilon\\) 只服务自动机。</p><p><span class="marginnote">Rabin–Scott 1959 子集构造。Hopcroft–Ullman 标准教材。龙书第 3 章用同一构造接词法。最小化（Hopcroft）本课点名：确定化之后可再压状态，不证 \\(O(n\\log n)\\)。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从 NFA 算每个子集的 \\(\\varepsilon\\)-闭包，对字母表每个符号画转移，起点是 \\(\\varepsilon\\text{-closure}(\\{q_0\\})\\)，含原接受态的子集为接受。模拟 NFA 也可在运行期维护集合，等价于懒确定化。</p>',13)),(n(),s(A,null,{default:o(()=>[i(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20NFA%5B%22NFA%20%2B%20%CE%B5%22%5D%20--%3E%20SUB%5B%22%E5%AD%90%E9%9B%86%E6%9E%84%E9%80%A0%22%5D%0A%20%20SUB%20--%3E%20DFA%5B%22DFA%22%5D%0A%20%20DFA%20--%3E%20MIN%5B%22%E5%8F%AF%E9%80%89%E6%9C%80%E5%B0%8F%E5%8C%96%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,[e("a",{href:"/cs/fsm-control"},"组成课 FSM"),t(" 是硬件控制；这里的状态是词法位置。对象同类，输入是源字符。")],-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"DFA 无 \\(\\varepsilon\\)、转移全。最长匹配：跑到死再回最后接受，依赖确定性。NFA 直接模拟要克隆光标，词法器通常不在运行期这么做。补、交对 DFA 容易（乘积），对 NFA 也可，本课不写积自动机全文。",-1)),(n(),s(A,null,{default:o(()=>[i(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q0%5B%22NFA%EF%BC%9Aq0%22%5D%20--%3E%7C%22a%22%7C%20Q1%5B%22NFA%EF%BC%9Aq1%22%5D%0A%20%20Q1%20--%3E%7C%22a%22%7C%20Q1%0A%20%20Q1%20--%3E%7C%22b%22%7C%20Q2%5B%22NFA%EF%BC%9Aq2%20%E6%8E%A5%E5%8F%97%22%5D%0A%20%20A%5B%22DFA%EF%BC%9A%EF%BD%9Bq0%EF%BD%9D%22%5D%20--%3E%7C%22a%22%7C%20B%5B%22DFA%EF%BC%9A%EF%BD%9Bq1%EF%BD%9D%22%5D%0A%20%20B%20--%3E%7C%22a%22%7C%20B%0A%20%20B%20--%3E%7C%22b%22%7C%20C%5B%22DFA%EF%BC%9A%EF%BD%9Bq2%EF%BD%9D%20%E6%8E%A5%E5%8F%97%22%5D%0A"})]),fallback:o(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=l('<p>这张图回答：子集构造在一个最小例子上怎么算。同一语言，NFA 里 q0 读 a 有歧义（可停在 q0 或走 q1）；确定化后 DFA 用「{q1}」一个状态顶掉这步分叉——每个字符的后继从此唯一。</p><p><span class="marginnote">常见误区：初学者容易以为 NFA 的「非确定」等于随机或能力更强。它只是「多路并行」的记法，语言类与 DFA 完全相同；真正跳出正则要靠栈（CFG），有限状态加再多非确定也还是正则。</span></p><p>不要把 CFG 的分析栈当成 NFA 的非确定：嵌套不是有限状态。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把正则式写成自动机（下一课 Thompson）。不证 Myhill–Nerode。后课默认：词法 DFA 与 NFA 认同一语言；正则到 NFA 的结构归纳是下一缺口。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NFA 与 DFA 认同一类正则语言；子集构造确定化。</li><li>状态数最坏指数，发生在生成期。</li><li>运行期词法用 DFA；正则的构造下一课。</li><li>出处：Rabin and Scott, 1959；Hopcroft and Ullman；龙书第 3 章。</li></ul>',7))])}const C=p(D,[["render",f]]);export{u as __pageData,C as default};
